#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

int main(void) {
    int srv = socket(AF_INET, SOCK_STREAM, 0);          /* TCP socket */
    int yes = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof yes);

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);           /* all local interfaces */
    addr.sin_port = htons(9000);                        /* network byte order! */

    bind(srv, (struct sockaddr *)&addr, sizeof addr);   /* claim IP:port */
    listen(srv, 16);                                    /* accept queue depth */

    int cli = accept(srv, NULL, NULL);                  /* one fd per client */
    char buf[256];
    ssize_t n = read(cli, buf, sizeof buf);             /* blocks until data */
    if (n > 0) write(cli, buf, (size_t)n);              /* echo it back */
    close(cli);
    close(srv);
    return 0;
}

